import{_ as o,l as i,o as a,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"会话保证","description":"","frontmatter":{"title":"会话保证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/session-guarantees.md","filePath":"cs/session-guarantees.md","lastUpdated":1789023840000}'),h={name:"cs/session-guarantees.md"};function u(_,e,E,B,m,f){const s=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="会话保证" tabindex="-1">会话保证 <a class="header-anchor" href="#会话保证" aria-label="Permalink to &quot;会话保证&quot;">​</a></h1><div class="epigraph"><p>全局可以最终一致，单个客户端仍要求：读到自己的写、单调读、因果读。保证绑在会话，不绑在全系统线性化点。</p><footer>—— 据 Terry, Demers, Petersen, Spreitzer, Theimer and Welch, Session Guarantees for Weakly Consistent Replicated Data, PDIS 1994 整理</footer></div><p>上一课<a href="/cs/crdt">CRDT</a>解决副本怎么并。缺口是<strong>用户体验</strong>：刷新页面看见自己刚提交的评论消失，半格再正确也像丢数据。本课把弱系统上的客户端承诺拆成几条，不把它们升级成<a href="/cs/linearizability">线性一致</a>。后课状态机复制才把全局序买回来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Terry 等四条（常加因果）：</p><ul><li><strong>Read Your Writes</strong>：会话内读看到本会话已提交的写。</li><li><strong>Monotonic Reads</strong>：一次读到某版本后，后续读不更旧。</li><li><strong>Writes Follow Reads</strong>：本会话读过的写，成为后续写的因果前驱。</li><li><strong>Monotonic Writes</strong>：本会话的写按程序序被所有副本看见。</li></ul><p>缺口：实现靠会话粘滞（打同一副本）或带版本向量的读修复，不是靠 \\(R+W\\gt n\\)。移动客户端换接入点会破粘滞，必须把向量放进 cookie 或令牌。</p><p><span class="marginnote">Bayou 与 Terry 的会话论文是移动弱复制的同一脉络。因果会话 ≈ 客户端视角的<a href="/cs/sequential-causal-consistency">因果一致</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协调者记住会话的 <code>read-set</code>/<code>write-set</code> 向量。读：只接受 \\(\\ge\\) 该向量的副本，或等反熵。写：把依赖向量附上。负载均衡必须读会话粘滞位，随机打节点会破 RYW。</p>',10)),(a(),l(p,null,{default:r(()=>[c(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SID%5B%22%E4%BC%9A%E8%AF%9D%E4%BB%A4%E7%89%8C%20%2F%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20LB%5B%22%E7%B2%98%E6%BB%9E%E6%88%96%E9%80%89%E5%A4%9F%E6%96%B0%E7%9A%84%E5%89%AF%E6%9C%AC%22%5D%0A%20%20LB%20--%3E%20RYW%5B%22%E8%AF%BB%E5%B7%B1%E4%B9%8B%E5%86%99%22%5D%0A%20%20LB%20--%3E%20MR%5B%22%E5%8D%95%E8%B0%83%E8%AF%BB%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与线性一致：另一会话的实时在先写，本会话仍可读旧——允许。只保证「我自己的故事连贯」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价：为等够新的副本，可用性向 CP 靠一截，但范围限于该会话关心的键前缀，不是全局多数派。这是在<a href="/cs/eventual-consistency">最终一致</a>上打补丁，不是偷偷换 CAP 格。</p><p>Cookies 丢失则会话重置，保证从零开始，用户又看见「自己的写暂时不见」——产品层要提示。多设备同一账号是多个会话，RYW 不跨设备，除非共享向量。</p><p>本课不把 HTTP cookie 安全模型写进来。也不把「会话」写成 Web 登录课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 COPS 的因果+ 全部内容，不引入事务快照隔离。后课默认：弱存储的产品承诺先问四条会话；要跨客户端实时则升级复制状态机。LWW 丢的更新，会话保证找不回来。</p><p>连贯是客户端的局部线性幻觉。幻觉的边界就是会话令牌的边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>会话保证是弱复制上的客户端连贯，不是全局线性一致。</li><li>RYW 与单调读最常用；靠粘滞或携带向量。</li><li>换节点必须迁移令牌，否则保证掉档。</li><li>出处：Terry et al., PDIS 1994。</li></ul>',10))])}const A=o(h,[["render",u]]);export{g as __pageData,A as default};
